import{_ as i,C as t,o as d,c,a2 as o,E as n}from"./chunks/framework.TaNiW7i8.js";const f=JSON.parse(`{"title":"Connecter l'agent","description":"","frontmatter":{"title":"Connecter l'agent"},"headers":[],"relativePath":"agent/connecter.md","filePath":"agent/connecter.md"}`),l={name:"agent/connecter.md"};function u(p,e,g,m,h,v){const s=t("Ask"),r=t("AskExample"),a=t("Capture");return d(),c("div",null,[e[0]||(e[0]=o('<h1 id="connecter-l-agent" tabindex="-1">Connecter l&#39;agent <a class="header-anchor" href="#connecter-l-agent" aria-label="Permalink to &quot;Connecter l&#39;agent&quot;">​</a></h1><p>Ce parcours sert à brancher votre assistant sur Kessho, puis à vérifier qu&#39;il voit la mémoire. Vous le faites une fois par machine ; l&#39;écran lui-même est décrit dans <a href="/Kessho/guide/agents.html">Connecter ses agents</a>.</p><h2 id="ce-que-vous-demandez-a-l-agent" tabindex="-1">Ce que vous demandez à l&#39;agent <a class="header-anchor" href="#ce-que-vous-demandez-a-l-agent" aria-label="Permalink to &quot;Ce que vous demandez à l&#39;agent&quot;">​</a></h2><p>Brancher un client est un geste de l&#39;<strong>application</strong>, pas de l&#39;agent : aucun outil MCP ne déploie quoi que ce soit. Une fois le client branché, vous vérifiez par deux demandes.</p>',4)),n(s,{say:"Quels outils Kessho me donne-t-il ?",verb:"mem_help",family:"maintenance"}),n(r,{tool:"mem_list"}),e[1]||(e[1]=o('<h2 id="ce-que-fait-l-application" tabindex="-1">Ce que fait l&#39;application <a class="header-anchor" href="#ce-que-fait-l-application" aria-label="Permalink to &quot;Ce que fait l&#39;application&quot;">​</a></h2><p>Au clic sur <strong>Auto-injecter</strong> (ou, au premier lancement, <strong>Déclarer Kessho à mes assistants</strong>), Kessho traite d&#39;un coup tous les clients détectés. Pour chacun :</p><ol><li>il sauvegarde le fichier de configuration, puis y écrit une entrée nommée <code>kessho</code> qui lance son serveur, sans argument ni permission ;</li><li>si cette déclaration a réussi, il dépose les <strong>procédures</strong> du client quand il en a (voir ci-dessous).</li></ol><p>Les dix clients, ce que Kessho écrit chez chacun :</p><table tabindex="0"><thead><tr><th>Client</th><th>Déclaration du serveur</th><th>Procédures déposées sous</th></tr></thead><tbody><tr><td>Claude Code</td><td><code>~/.claude.json</code></td><td><code>~/.claude/</code> (ou <code>$CLAUDE_CONFIG_DIR</code>)</td></tr><tr><td>GitHub Copilot CLI</td><td><code>~/.copilot/mcp-config.json</code></td><td><code>~/.copilot/</code> (ou <code>$COPILOT_HOME</code>)</td></tr><tr><td>Codex</td><td><code>~/.codex/config.toml</code></td><td><code>~/.codex/</code></td></tr><tr><td>Gemini CLI</td><td><code>~/.gemini/settings.json</code></td><td><code>~/.gemini/</code></td></tr><tr><td>Mistral Vibe</td><td><code>~/.vibe/config.toml</code></td><td><code>~/.vibe/</code></td></tr><tr><td>Claude Desktop</td><td><code>~/Library/Application Support/Claude/claude_desktop_config.json</code> (macOS)</td><td>aucune</td></tr><tr><td>opencode</td><td><code>~/.config/opencode/opencode.json</code></td><td>aucune</td></tr><tr><td>Antigravity, Antigravity (application), Antigravity (CLI)</td><td><code>~/.gemini/config/mcp_config.json</code>, <code>~/.gemini/antigravity/mcp_config.json</code>, <code>~/.gemini/antigravity-cli/mcp_config.json</code></td><td>aucune</td></tr></tbody></table><p>« Aucune » veut dire : le serveur est déclaré et l&#39;agent voit les outils, mais Kessho ne dépose rien qui lui dise <strong>quand</strong> les appeler. Le code le déclare explicitement, dans sa liste des clients sans procédures (<code>SANS_PROCEDURES</code>) : pour Claude Desktop et opencode, l&#39;endroit où ces clients liraient des procédures n&#39;est pas établi ; pour Antigravity, il n&#39;a jamais été mesuré. Avec ces clients, c&#39;est à vous de demander l&#39;outil (« appelle <code>mem_recall</code> sur kessho-docs »).</p><h3 id="les-procedures" tabindex="-1">Les procédures <a class="header-anchor" href="#les-procedures" aria-label="Permalink to &quot;Les procédures&quot;">​</a></h3><p>Ce sont des fichiers (compétences, commandes) que le client lit : une par outil ou par geste, par exemple <code>mem-recall</code> ou <code>mem-archive</code>. Elles disent à l&#39;agent <strong>quand</strong> appeler l&#39;outil, sans que vous tapiez de commande :</p><ul><li>une envie de reprendre (« on reprend », « où en étions-nous ? ») ou une question sur le passé (« qu&#39;avait-on décidé ? ») déclenche la reprise, voir <a href="/Kessho/agent/reprendre.html">Reprendre un projet</a> ;</li><li>un signal de fin (« on s&#39;arrête », « j&#39;ai fini ») déclenche l&#39;archivage complet, voir <a href="/Kessho/agent/archiver.html">Archiver une session</a> ;</li><li>les autres (chercher, noter, renommer, synchroniser…) se déclenchent sur l&#39;intention que vous exprimez.</li></ul><p>Une procédure que vous avez modifiée à la main n&#39;est <strong>jamais écrasée</strong> : Kessho la laisse en place et l&#39;écran la signale (« modifiée à la main »). Les procédures qu&#39;il a déposées lui-même sont mises à jour au déploiement suivant.</p><h2 id="ce-que-vous-voyez" tabindex="-1">Ce que vous voyez <a class="header-anchor" href="#ce-que-vous-voyez" aria-label="Permalink to &quot;Ce que vous voyez&quot;">​</a></h2>',11)),n(a,{name:"connecteurs",alt:"L'écran des connecteurs d'agents MCP après « Auto-injecter » : chaque client détecté est passé à « Déployé »."}),e[2]||(e[2]=o('<ul><li><strong>Réglages › Connecteurs MCP</strong> : le tableau des clients avec leur <strong>État</strong> (<strong>Déployé</strong>, <strong>À configurer</strong>, <strong>Non détecté</strong>…), les boutons <strong>Sonder le serveur</strong>, <strong>Auto-injecter</strong> et <strong>Désinstaller</strong>, et le panneau <strong>Déploiement</strong>. Les libellés sont expliqués dans <a href="/Kessho/guide/agents.html">Connecter ses agents</a>.</li><li><strong>Sonder le serveur</strong> mesure le serveur de Kessho (« Serveur joignable · 42 ms »). Il ne dit <strong>pas</strong> qu&#39;un assistant l&#39;utilise : pour cela, demandez à l&#39;agent un outil (les deux demandes ci-dessus) et regardez s&#39;il répond avec vos projets.</li><li>La barre d&#39;état affiche <strong>AGENTS 8/8</strong> sur la capture ci-dessus (le chiffre dépend de votre poste) : combien de clients détectés portent Kessho.</li><li>Sous un client, l&#39;écran liste les procédures retirées ou épargnées (« modifiée à la main »), s&#39;il y en a.</li></ul>',1))])}const C=i(l,[["render",u]]);export{f as __pageData,C as default};
